 ["Standard Rumble"] = "Стандартная вибрация",
 ["Standard balance across all categories"] = "Стандартный баланс во всех категориях",
 ["Starts high, fades into a low hum."] = "Начинается на высокой частоте и переходит в низкий гул.",
 ["Status: %s"] = "Статус: %s",
 ["Stealth Breathing Wave"] = "Дыхательная волна незаметности",
